def is_golomb(marks, new):
    diffs = set()
    for i in range(len(marks)):
        diff = new - marks[i]
        if diff in diffs:
            return False
        diffs.add(diff)
    return True

def find_golomb(current, n, max_len=100):
    if len(current) == n:
        return current
    start = current[-1] + 1
    for pos in range(start, max_len):
        if all(is_golomb(current, pos) for _ in [0]):  # just check
            # better way
            all_diffs = set()
            for i in range(len(current)):
                for j in range(i+1, len(current)):
                    all_diffs.add(current[j] - current[i])
            new_diffs = [pos - m for m in current]
            if any(d in all_diffs for d in new_diffs) or len(set(new_diffs)) < len(new_diffs):
                continue
            res = find_golomb(current + [pos], n, max_len)
            if res:
                return res
    return None

result = find_golomb([0,2], 7, 30)
print(result)
